          auto_ui_aaa76481a83f: "เพื่อปรับปรุงประสิทธิภาพ ความเสถียร และประสบการณ์การใช้งานของระบบ",
          auto_ui_33964fd166a9: "เพื่อป้องกันการใช้งานที่ผิดปกติ การโจมตี และพฤติกรรมที่เสี่ยงต่อความปลอดภัย",
          auto_ui_ab9c38db4f8c: "เพื่อช่วยตรวจสอบปัญหาเชิงเทคนิคและให้การซัพพอร์ตผู้ใช้งาน",
          auto_ui_f4d6a95bda51: "3. การจัดเก็บและความปลอดภัยของข้อมูล (Storage & Security)",
          auto_ui_783406189ad4: "มีมาตรการที่เหมาะสมเพื่อป้องกันการเข้าถึงข้อมูลโดยไม่ได้รับอนุญาต",
          auto_ui_9d13624c7389: "จำกัดการเข้าถึงข้อมูลเฉพาะส่วนที่จำเป็นต่อการดูแลระบบและการซัพพอร์ต",
          auto_ui_214b5731b674: "ข้อมูลบางส่วนอาจถูกเก็บตามระยะเวลาที่จำเป็นต่อการให้บริการและตรวจสอบความถูกต้องของระบบ",
          auto_ui_bffed1e6c587: "4. การเปิดเผยข้อมูลต่อบุคคลที่สาม (Third-party Disclosure)",
          auto_ui_24baf2d38f33: "เราไม่มีนโยบายขายข้อมูลส่วนบุคคลของผู้ใช้งาน",
          auto_ui_9f85104f824a: "อาจมีการส่งต่อข้อมูลที่จำเป็นไปยังผู้ให้บริการภายนอกเฉพาะกรณีที่เกี่ยวข้องกับการทำงานของระบบ (เช่น Discord API หรือผู้ให้บริการชำระเงิน)",
          auto_ui_6abe2213d618: "การเปิดเผยข้อมูลจะจำกัดเท่าที่จำเป็น และอยู่ภายใต้ข้อกำหนดด้านความปลอดภัยที่เหมาะสม",
          auto_ui_25a4f85698e3: "5. สิทธิของผู้ใช้งานและผู้ดูแลเซิร์ฟเวอร์ (Your Rights)",
          auto_ui_60da5f983e2b: "ผู้ดูแลเซิร์ฟเวอร์สามารถปรับเปลี่ยนการตั้งค่าระบบที่เกี่ยวข้องกับข้อมูลได้ผ่าน Dashboard",
          auto_ui_63f701dbed25: "หากต้องการสอบถามหรือต้องการให้ตรวจสอบข้อมูลที่เกี่ยวข้อง สามารถติดต่อทีมงานได้โดยตรง",
