          auto_ui_f851d01147ec: "เช่น ไอดีกิลด์ ไอดีห้อง ไอดียศ ไอดีผู้ใช้ และข้อมูลที่จำเป็นต่อการทำงานของคำสั่งและโมดูลต่างๆ",
